public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = Integer.parseInt(sc.next());

    PrintWriter pw = new PrintWriter(System.out);
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n - i; j++) {
            for (int k = 0; k <= n - i - j; k++) {
                pw.println(i + " " + j + " " + k);
            }
        }
    }
    pw.flush();
}
